    exampleOutput: "### Edge-Case Matrix & Vitest Suite\n\n```typescript\nimport { describe, it, expect, vi, beforeEach } from 'vitest';\nimport { transferFunds } from './transfer';\nimport { InvalidAmountError, SameAccountError, InsufficientFundsError } from './errors';\n\ndescribe('transferFunds()', () => {\n  let mockLedger: any;\n\n  beforeEach(() => {\n    mockLedger = {\n      getBalance: vi.fn(),\n      executeAtomicTransfer: vi.fn(),\n    };\n  });\n\n  describe('Input Validations', () => {\n    it('should throw InvalidAmountError when amount is zero or negative', async () => {\n      await expect(transferFunds('acc-1', 'acc-2', 0, mockLedger))\n        .rejects.toThrow(InvalidAmountError);\n      await expect(transferFunds('acc-1', 'acc-2', -500, mockLedger))\n        .rejects.toThrow(InvalidAmountError);\n      expect(mockLedger.getBalance).not.toHaveBeenCalled();\n    });\n\n    it('should throw SameAccountError when sender and recipient are identical', async () => {\n      await expect(transferFunds('acc-1', 'acc-1', 1000, mockLedger))\n        .rejects.toThrow(SameAccountError);\n    });\n  });\n\n  describe('Balance & Execution Branches', () => {\n    it('should throw InsufficientFundsError when balance is less than transfer amount', async () => {\n      mockLedger.getBalance.mockResolvedValue(499);\n      await expect(transferFunds('acc-1', 'acc-2', 500, mockLedger))\n        .rejects.toThrow(InsufficientFundsError);\n      expect(mockLedger.executeAtomicTransfer).not.toHaveBeenCalled();\n    });\n\n    it('should successfully transfer when balance exactly equals amount', async () => {\n      mockLedger.getBalance.mockResolvedValue(500);\n      mockLedger.executeAtomicTransfer.mockResolvedValue({ status: 'COMPLETED', txId: 'tx-99' });\n\n      const result = await transferFunds('acc-1', 'acc-2', 500, mockLedger);\n      expect(result.status).toBe('COMPLETED');\n      expect(mockLedger.executeAtomicTransfer).toHaveBeenCalledWith('acc-1', 'acc-2', 500);\n    });\n  });\n});\n```",
